MAP
  NAME "unoceandecadeatlas"
  STATUS ON
  EXTENT -180 -90 180 90
  UNITS DD
  
  CONFIG "MS_ERRORFILE" "stderr"
  CONFIG "GDAL_HTTP_TIMEOUT" "30"
  CONFIG "CPL_DEBUG" "ON"
  CONFIG "GDAL_HTTP_VERBOSE" "YES"
  DEBUG 5
  
  PROJECTION
    "init=epsg:8857"
  END
  
  WEB
    METADATA
      "wms_title" "UN Ocean Decade Atlas"
      "wms_abstract" "This Web Map Service wraps non-WMS data sources for layers in the UN Ocean Decade's Digital Atlas to allow them to be displayed in the atlas user interface, derived from the EMODnet Central Portal Map Viewer software.'"
      "wms_onlineresource" "http://localhost:8080/?"
      "wms_srs" "EPSG:3857 EPSG:4326 EPSG:8857"
      "wms_enable_request" "*"
    END
  END

  INCLUDE "symbols/circle.map"
  
  INCLUDE "layers/01_coastpredict_pilot_sites.map"
  INCLUDE "layers/02_argo_float_locations.map"
  INCLUDE "layers/03_ocean_networks_canada_observatories.map"
  INCLUDE "layers/04_ocean_prediction_systems_atlas.map"
  INCLUDE "layers/05_protected_seas_navigator.map"  
  
END
